INSERT INTO public.glossary_terms
  ("id","term","aliases","definition","learnMoreUrl","isActive","createdAt","updatedAt")
VALUES
  ('cg2611_2b6e2b147e54e669798c6b','Acyclical',ARRAY[]::text[],'An economic variable is acyclical when it shows no consistent tendency to rise or fall with the business cycle.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_2d9e3f385abd387b071198','Ad valorem tariff',ARRAY[]::text[],'A customs duty calculated as a percentage of the imported product''s declared customs value rather than a fixed amount per unit.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_f2116a9edda87d12142b5d','Additional Tier 1 capital',ARRAY[]::text[],'A class of bank regulatory capital, often issued through perpetual instruments capable of absorbing losses by conversion or write-down.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_8cfc0407a27946c8cf55a0','Adjustment gap',ARRAY[]::text[],'The delay between a change in economic circumstances and the adjustment of wages or employment towards a new equilibrium.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_06e8fcb1a952ed10df885b','Administrative feasibility',ARRAY[]::text[],'Whether a proposed policy can be put into effect with the staff, information and institutions available to government.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_4b360ace68dacff91c0d3e','Aggregate output',ARRAY[]::text[],'The total amount of goods and services produced throughout an economy over a specified period.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_b971230a09f2658d5fe11f','Agricultural domestic support',ARRAY[]::text[],'Government assistance to domestic farming, including payments or price-support measures, classified under international agricultural trade rules.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_dcc5cdb6bbf46ca67b0cca','Agricultural tariffication',ARRAY[]::text[],'The conversion of certain non-tariff agricultural import restrictions into equivalent tariffs during a trade-policy reform.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_d182f4c5592aad1689c910','Alignment adjustment',ARRAY[]::text[],'An adjustment used by statisticians to reconcile different estimates of GDP based on production, income and spending.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_aa6b7ae3a7c927ddea3fa9','Annual percentage rate',ARRAY[]::text[],'A standardised annual measure of borrowing cost that can incorporate interest and certain fees, enabling comparisons between credit offers.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_fef1a9c4034cec9232cd52','Annual percentage rate of charge',ARRAY[]::text[],'A measure of the yearly cost of consumer credit or mortgage borrowing, calculated under applicable disclosure rules.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_c82cff864155e65db1348d','Appellation of origin',ARRAY[]::text[],'A designation identifying goods whose qualities or characteristics are essentially linked to their place of production.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_d146a8983d58e1a5266318','Asset Purchase Facility',ARRAY[]::text[],'The Bank of England arrangement used to finance purchases of government and certain other bonds for monetary policy purposes, particularly during quantitative easing.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_be838a2ae1b5d6baaf9ba1','Assets under management',ARRAY[]::text[],'The total market value of investments managed by a fund manager or institution on behalf of clients at a particular date.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_90d1a0db02e200691fb003','Average weekly earnings',ARRAY[]::text[],'A measure of average pay received by employees over a week, used to track wage developments and labour-market pressures.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_93e54a276fbebfb56770a2','Bank holding company',ARRAY[]::text[],'A parent company that owns or controls a bank and may also hold interests in other financial businesses.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_405915791ddeff4b639247','Bank Liabilities Survey',ARRAY[]::text[],'A Bank of England survey gathering information from lenders on funding conditions and how these affect the availability and cost of credit.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_0c026953b5440a9cf0dafc','Bank Recovery and Resolution Directive',ARRAY[]::text[],'European Union legislation establishing tools for preparing for and managing the failure of banks and specified investment firms.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_dfd4eaf22b27c8c34c6eb2','Bank resolution',ARRAY[]::text[],'The orderly handling of a failing bank through legal powers intended to preserve critical functions and limit disruption to financial stability.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_ebbcbdeb23322664f7243b','Bargaining gap',ARRAY[]::text[],'The difference between the real wage that motivates workers and the real wage consistent with firms'' preferred price markups.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_ecb0d0bc1d94f3a89909cc','Basel Committee on Banking Supervision',ARRAY[]::text[],'An international committee of banking supervisors that develops global standards for bank regulation, including the Basel capital and liquidity frameworks.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_303a447216752fdaf9bbef','Basel Convention',ARRAY[]::text[],'An international treaty controlling cross-border movement and disposal of certain hazardous wastes and requiring environmentally sound management.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_241e992033c88fc98bf13e','Basel III',ARRAY[]::text[],'An international regulatory framework strengthening bank capital, liquidity and leverage requirements after the 2007–09 financial crisis.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_9ac3b8bb5a1f86daac09fa','Basic prices',ARRAY[]::text[],'Prices received by producers excluding taxes on products and including subsidies on products, as used in national accounts.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_9ae2da38911e5f8b60efd3','Berne Convention',ARRAY[]::text[],'An international treaty establishing common standards for copyright protection of literary and artistic works between member countries.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_8b0aa13b59864331c3d3a4','Border tax adjustment',ARRAY[]::text[],'A tax measure applied to imports or exports to align relevant tax treatment with domestically produced goods under applicable rules.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_0e3d59671fd281d133e91d','Bound tariff rate',ARRAY[]::text[],'The maximum customs duty a WTO member has committed to apply to a product under its tariff schedule, subject to WTO rules.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_89ff8ab96b8a7753756d65','Cabotage',ARRAY[]::text[],'Transport between points within one country, often regulated separately from international shipping or aviation services.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_8d49be8a1b23281d917459','Capacity-constrained firm',ARRAY[]::text[],'A producer facing demand greater than the output it can supply with its available resources and current productive capacity.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_88e26f6235e91f15d2ad36','Capital Requirements Directive',ARRAY[]::text[],'European legislation governing aspects of bank prudential supervision, governance and capital buffers alongside directly applicable regulatory rules.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_bac0e291cb9a72decef5a7','Capital Requirements Regulation',ARRAY[]::text[],'European legislation establishing detailed prudential requirements for banks and certain investment firms, including capital and liquidity provisions.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_e5a485f4f34fd0b1f83407','Capitalism',ARRAY[]::text[],'An economic system in which private ownership, firms and markets play major roles in organising production and exchange.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_ea66377b3b438e9be95d01','Capitalist revolution',ARRAY[]::text[],'The combination of technological development and institutional change that helped capitalism transform production and living standards.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_5c5bb3b3fdcab2270aa6c7','Central bank digital currency',ARRAY[]::text[],'A digital form of central-bank money made available to specified users, with design choices determining access and payment characteristics.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_0adb23cfe612ec1389d0f5','Central counterparty',ARRAY[]::text[],'An institution that stands between counterparties to cleared trades and manages their obligations and default risk.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_1609bad26a5a1006f8ea91','Central securities depository',ARRAY[]::text[],'An institution that holds securities records and supports the settlement and safekeeping of financial instruments.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_5a6bb0db7753d4877df631','Chained volume measures',ARRAY[]::text[],'Measures of economic output adjusted for price changes by linking volume growth between successive periods using updated price weights.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_cd6e4fcb79e64ae6118280','CITES treaty',ARRAY[]::text[],'The international convention regulating trade in endangered wild animals and plants through listed species and permit requirements.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_a0807abeaf8b44d0bd763e','Claimant count',ARRAY[]::text[],'A UK administrative measure of people claiming specified unemployment-related benefits; it differs from survey-based unemployment.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_15f946753295053791e5d2','Commercial presence in services trade',ARRAY[]::text[],'The supply of services through an establishment, such as a branch or subsidiary, in another country''s market.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_c9ceac1fbba38340790581','Commercial real estate',ARRAY[]::text[],'Buildings and land held for commercial use or investment, including offices, retail premises, warehouses and rented industrial space.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_ec5cb3e6e19049c4778780','Commodity',ARRAY[]::text[],'A widely traded physical product, such as copper, wheat or crude oil, whose quality is relatively standardised.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_f8bee60aee02005be09531','Compensation of employees',ARRAY[]::text[],'Wages and salaries plus employers'' social contributions attributable to employees, measured in the national accounts.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_25e760f29c76914e6ea290','Competitive equilibrium',ARRAY[]::text[],'A market outcome in which price-taking buyers and sellers are individually optimising and planned supply equals planned demand.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_69975d39b9b268a0db7683','Competitive price-taking behaviour',ARRAY[]::text[],'Conduct by buyers and sellers whose individual decisions cannot materially affect the market price, so they accept it as given.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_fa3d9f08e318b23b3da737','Constant-price series',ARRAY[]::text[],'A series valued using prices from a reference period, designed to separate changes in quantities from inflation.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_0356e312f0bd23ed23bd4a','Cooperative firm',ARRAY[]::text[],'An enterprise owned or controlled primarily by its workers or members rather than outside shareholders.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_326ff785f323ad40bbfb03','Copyright piracy',ARRAY[]::text[],'Unauthorised copying and commercial distribution of protected creative material in ways that infringe copyright.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_3ad312362de2d7af9d21f6','Correlation',ARRAY[]::text[],'A statistical association between variables, without necessarily showing that one causes the other.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_c4a19153ac8d10c9c5c2ca','Cost-benefit analysis',ARRAY[]::text[],'A structured comparison of the expected costs and benefits of a project or policy, often expressing them in present-value terms.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_6248a0f83f08e07dd83c1f','Countercyclical capital buffer',ARRAY[]::text[],'Additional bank capital that regulators can increase when systemic credit risks grow and release during downturns.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_e4ea019c9d2f3f47dbbcc5','Counterfeit trade-mark goods',ARRAY[]::text[],'Products that carry unauthorised marks intended to pass off goods as those of another legitimate trade-mark owner.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_9ce1101c3644c8db29570a','CPIH inflation',ARRAY[]::text[],'Inflation measured by the UK Consumer Prices Index including owner occupiers'' housing costs, an official measure of consumer price changes.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_f40cd8beebe20ed60b501c','Credit Conditions Review',ARRAY[]::text[],'A former Bank of England publication assessing bank funding and household and corporate borrowing conditions, last published in 2018.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_0054c7f21767cd3496107e','Credit Conditions Survey',ARRAY[]::text[],'A regular Bank of England survey of lenders about changes in the availability, pricing and demand for credit to households and businesses.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_0a4903a475c06f7599baf3','Credit default swap',ARRAY[]::text[],'A derivative contract in which a protection buyer pays for compensation if a specified borrower experiences a defined credit event.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_de74b8c99bb148a2c4b5ba','Credit rating agency',ARRAY[]::text[],'A business that assesses the creditworthiness of borrowers or securities and publishes or sells credit ratings.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_a0e0b9e30282ae31253aac','Credit rationing',ARRAY[]::text[],'A limit on the amount of credit lenders are willing to provide, even when some borrowers would accept higher interest rates.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_27ef25b643d5ff6b278117','Credit valuation adjustment',ARRAY[]::text[],'An adjustment reflecting the effect of a derivative counterparty''s credit risk on the estimated fair value of a contract.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_0afa589bec7b5688f58f07','Current account deficit',ARRAY[]::text[],'A negative balance on the current account, meaning net payments abroad for trade, income and transfers exceed corresponding receipts.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_900b1c07e1c347220c7b6e','Current account surplus',ARRAY[]::text[],'A positive balance on the current account, when receipts from abroad for trade, income and transfers exceed associated payments.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_8259ea211d8b1833387a00','Current-price series',ARRAY[]::text[],'Economic figures measured using the prices prevailing in each period, without removing the effects of inflation.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_c6e91de744d5c7e5ef1a1a','Customs duty',ARRAY[]::text[],'A tax charged on goods crossing a customs boundary, frequently applied to imports and calculated by value, weight or quantity.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_095f9afcbc2e58918681ef','Debt-service ratio',ARRAY[]::text[],'The share of a borrower''s income or cash flow used to meet interest and principal repayments over a specified period.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_448d1af9c7830369a3aee1','Debt-to-income ratio',ARRAY[]::text[],'A borrower''s outstanding debt relative to their income, often used when assessing household leverage or loan affordability.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_51591a89cb6b7cb9db5d23','Decreasing returns to scale',ARRAY[]::text[],'A production pattern in which increasing all inputs by a given proportion increases output by a smaller proportion.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_3c3a87bc6841006584392f','Deferred tax asset',ARRAY[]::text[],'An accounting asset representing future tax benefits arising from deductible differences, unused losses or credits, subject to relevant recognition criteria.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_539c7308801be2a994aa6f','Deficiency payment',ARRAY[]::text[],'A public payment to producers that makes up some difference between a target or support price and a prevailing market price.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_a2186c9d374fbed82d770a','Delivery versus payment',ARRAY[]::text[],'A securities settlement arrangement linking transfer of securities with payment, reducing the risk that one occurs without the other.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_84da958be30e203072176d','Demand side of a market',ARRAY[]::text[],'The buyers who wish to obtain a product or resource at different prices, as distinct from its suppliers.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_04bdc7b97389f24bd73889','Demand-side economics',ARRAY[]::text[],'Analysis that emphasises how spending decisions influence output, employment and fluctuations in activity.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_d4b15d3172aab8eac0395e','Direct taxation',ARRAY[]::text[],'Taxes levied directly on income, profits or wealth, generally paid by the person or entity legally liable.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_dd56bc23f2e7c21f1e7f1d','Discount Window Facility',ARRAY[]::text[],'A Bank of England facility allowing eligible institutions to borrow liquid assets against collateral, typically to manage a temporary liquidity shortage.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_4f4ecee479a4057f6fbb4b','Disequilibrium rent',ARRAY[]::text[],'A temporary gain or loss arising because prices or quantities have not yet adjusted to changing market conditions.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_1411bca753217f21217e21','Distributed ledger technology',ARRAY[]::text[],'A method of maintaining shared transaction records across several computers using agreed protocols, without necessarily relying on one central record keeper.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_32a2a5218bc0909f3cb384','Division of labour',ARRAY[]::text[],'The specialisation of workers or businesses in different tasks within a wider production process.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_b91a5064714219857b0d73','Domestic systemically important bank',ARRAY[]::text[],'A bank whose disruption could materially harm its domestic financial system, even if it is not classified as globally systemic.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_32b9ede2b513871fc265e1','Dominant technology',ARRAY[]::text[],'A production method that can achieve the same output using no more of every input and less of at least one than alternatives.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_a23d8a056004bf8174799f','Earnings before interest and tax',ARRAY[]::text[],'An accounting measure of operating profit before deducting financing interest and corporate income tax.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_ab1ccb7796070cfe7618cf','EBITDA',ARRAY[]::text[],'Earnings before interest, taxes, depreciation and amortisation, a widely used but incomplete indicator of operating performance.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_00e2cd754b264afd21cf50','Economic contagion',ARRAY[]::text[],'The spread of financial or economic disturbances from one market, institution or country to others through shared exposures and reactions.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_c275501ef0110266eb280c','Economic contract',ARRAY[]::text[],'A legally enforceable or socially recognised agreement specifying obligations between parties to an economic exchange.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_185d7dfff6ea0c08f77ba2','Economic cooperation',ARRAY[]::text[],'Joint action by people or organisations to achieve a result that benefits the participants.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_59b07e59b3202e4a00a1e3','Economic cost',ARRAY[]::text[],'The full cost of an activity, including both money paid and the value of the best alternative use of resources.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_30693299df51085314c669','Economic rent',ARRAY[]::text[],'A payment or benefit above what someone would earn from their next-best available alternative.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_ba41fc0601c95ec0b674f2','Economic system',ARRAY[]::text[],'The institutions and arrangements through which a society organises production, distribution and consumption.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_de65805169f52289d0a98c','Effective lending rate',ARRAY[]::text[],'The average interest rate earned or charged on a group of loans, calculated from the interest paid and outstanding balances.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_8aa6dc10e33fca8cff659d','Emergency liquidity assistance',ARRAY[]::text[],'Exceptional central-bank support providing short-term liquidity to an institution facing acute funding difficulties under specified safeguards.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_68a2462717be2eda5394e8','Employment rate',ARRAY[]::text[],'The share of a specified working-age population that is employed, distinct from the unemployment rate''s labour-force denominator.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_7939390b748826cb05fb4d','Endogenous variable',ARRAY[]::text[],'A variable whose value is explained or jointly determined by the relationships within an economic model.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_0bcaa7a54c4c9caf9aff4d','Endowments in economics',ARRAY[]::text[],'The assets, abilities and resources that people bring to economic interaction, shaping their income opportunities and bargaining power.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_a61f49169def8e1a16bd00','Equilibrium rent',ARRAY[]::text[],'A benefit above opportunity cost that persists even once a market has adjusted and no further forces for change remain.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_ac50961178a32e1242031b','Euro area',ARRAY[]::text[],'The European Union countries that use the euro as their common currency and share monetary policy through the Eurosystem.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_eb731b73cfab2a9a22fa88','European Banking Authority',ARRAY[]::text[],'A European Union agency that develops technical standards and promotes consistent supervision and regulation of banking across participating states.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_69166c8df6d090be8869b4','European Central Bank',ARRAY[]::text[],'The central bank responsible for monetary policy in the euro area, working with national central banks in the Eurosystem.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_19f142feb30b7a61a7ef57','European Insurance and Occupational Pensions Authority',ARRAY[]::text[],'A European Union authority promoting consistent supervision of insurance companies and occupational pensions.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_9453469ba923e6ca6f1cae','European Market Infrastructure Regulation',ARRAY[]::text[],'European Union legislation governing aspects of derivatives clearing, reporting and risk management to reduce financial-market vulnerabilities.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_edc1d99a5fc954127b273d','European Supervisory Authorities',ARRAY[]::text[],'The European Union''s sectoral financial supervisory authorities for banking, securities, insurance and occupational pensions.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_67cbc4688a5240fa3ece45','European System of Accounts',ARRAY[]::text[],'The common accounting framework used across Europe to compile comparable national and sectoral economic statistics.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_c369626cd6690f351b0800','European System of Central Banks',ARRAY[]::text[],'The European Central Bank and the national central banks of all European Union countries, including those not using the euro.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_07ba82bb53a4604cd37f8d','European Systemic Risk Board',ARRAY[]::text[],'An EU body monitoring and assessing systemic risks to financial stability within the European financial system.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_df0bf45111e4f9bd79fe30','Exchange rate index',ARRAY[]::text[],'A weighted measure of a currency''s value against a basket of trading-partner currencies rather than a single exchange rate.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_5bf7c31370f25c47c609b9','Exogenous shock',ARRAY[]::text[],'An unexpected change originating outside a model that alters economic outcomes, such as a sudden disruption in imported energy supplies.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_79794ef14220a9767bf12d','Exogenous variable',ARRAY[]::text[],'A variable whose value is determined outside the relationships described by an economic model.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_71862f3b1da0d5a84660b6','Expected credit loss',ARRAY[]::text[],'A forward-looking estimate of losses from defaults on loans or other credit exposures, incorporating probability and severity.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_e786ffe1ee2da79e18b2bc','Expected inflation rate',ARRAY[]::text[],'The rate of price growth that households, firms or investors anticipate over a future period and use in financial or spending decisions.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_1e5fa246509c902014b00c','Export-performance requirement',ARRAY[]::text[],'A condition imposed on an investor that a specified share or quantity of production must be sold in foreign markets.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_12a6ad8cca1548fac21efc','Exposure at default',ARRAY[]::text[],'The estimated amount a lender is owed or exposed to when a borrower defaults, used in credit-risk calculations.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_65a4b713cb464ae245aed1','Expropriation risk',ARRAY[]::text[],'The possibility that a government or other actor takes an investor''s property without acceptable compensation.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_4930b4371585afbbc5cfc8','Factory-gate price',ARRAY[]::text[],'The amount charged by a manufacturer when goods leave the factory, before later distribution and retail margins.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_50d4a40509bf817f06d58f','Fairness in economic allocation',ARRAY[]::text[],'A judgement about whether the way resources or benefits are distributed meets an ethical standard.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_d26b97c8995ae86902b36d','Federal Open Market Committee',ARRAY[]::text[],'The Federal Reserve committee that sets the target range for the main US policy interest rate and directs monetary operations.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_d690c0904bb891dd63e3a2','Final consumption expenditure',ARRAY[]::text[],'Spending on goods and services used directly to meet the needs of households, governments or non-profit institutions.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_7d64691e2ea5d34b5dd962','Financial Conduct Authority',ARRAY[]::text[],'The UK regulator overseeing the conduct of financial-services firms, market integrity and aspects of consumer protection.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_c1d1c7c49b4a503c7e1de8','Financial flows versus stocks',ARRAY[]::text[],'The distinction between economic quantities measured over a period, such as income, and quantities measured at a point in time, such as wealth.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_6cab431b77525e270afe29','Financial intermediation services indirectly measured',ARRAY[]::text[],'The estimated value of some banking services provided through interest-rate spreads rather than explicit fees.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_39082b9420b1a77554f4db','Financial market infrastructure',ARRAY[]::text[],'The systems and institutions needed to execute, clear, settle and record transactions in securities, money and derivatives.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_fe996c67b61a06d42485e4','Financial Ombudsman Service',ARRAY[]::text[],'A UK dispute-resolution service that considers eligible complaints between consumers and financial-services businesses.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_45b08627e49b8fa6b7591c','Financial Policy Committee',ARRAY[]::text[],'The Bank of England committee responsible for monitoring risks to UK financial stability and taking macroprudential policy action.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_974b4a4b8b7bc2ddc1e55b','Financial Reporting Council',ARRAY[]::text[],'The United Kingdom''s regulator of auditors, accountants and corporate reporting, with responsibilities for governance and stewardship standards.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_9fec7cbae2f7e9b91cfacb','Financial Sector Assessment Program',ARRAY[]::text[],'An IMF and World Bank assessment framework examining a country''s financial system, regulatory arrangements and financial-stability vulnerabilities.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_93ad75d677dbb26ecc7ae6','Financial Services Compensation Scheme',ARRAY[]::text[],'The UK''s statutory scheme protecting eligible customers of authorised financial firms within applicable compensation limits.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_acd49ffb449f00e96f850b','Financial Stability Board',ARRAY[]::text[],'An international body coordinating work by financial authorities to identify vulnerabilities and strengthen global financial stability.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_52efb016f9b9b71856afa3','Firm-specific asset',ARRAY[]::text[],'A resource or skill that is more valuable in its present firm than in the owner''s next-best alternative.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_69fd75afc9e82561570bec','First-copy cost',ARRAY[]::text[],'The initial expense of producing an original information product, such as developing software or creating a film.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_583f8c90c8e2a14bd7a54a','Fiscal stimulus',ARRAY[]::text[],'A deliberate increase in public spending or reduction in taxes intended to support aggregate economic demand.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_c60fe48c09e9a2da55347b','Floating-rate note',ARRAY[]::text[],'A bond whose coupon varies periodically according to a reference interest rate plus or minus an agreed spread.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_3dfc9fed3f0ca602b2238d','Foreign exchange reserves',ARRAY[]::text[],'External assets in foreign currencies held by monetary authorities, available for purposes such as intervention and meeting external obligations.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_98d31b18385b601d3e1b84','Full employment',ARRAY[]::text[],'A situation in which most people who want work can find jobs, allowing for normal job changes and unavoidable frictions.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_9b922e7da7276876019427','Funding for Lending Scheme',ARRAY[]::text[],'A programme launched by the Bank of England and UK Treasury in 2012 to encourage bank and building-society lending to households and businesses.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_1a4b13d53ced10351dfe12','GATT Article XX exception',ARRAY[]::text[],'A provision allowing certain trade measures for legitimate public-policy purposes, subject to conditions preventing unjustified discrimination.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_319782687ae329c4ed6181','GDP expenditure approach',ARRAY[]::text[],'Measuring GDP by adding final consumption, investment, government demand and net exports of goods and services.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_206c97b03363689b5579e9','GDP income approach',ARRAY[]::text[],'Measuring GDP by adding the income generated through production, including employee compensation and operating surpluses.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_d3e2d1ac16831e5b514002','GDP output approach',ARRAY[]::text[],'Measuring gross domestic product by adding the value created by producers across industries, with the appropriate taxes and subsidies.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_1547434bbd76c9b62d1288','General Agreement on Tariffs and Trade',ARRAY[]::text[],'The treaty framework governing international trade in goods, negotiated in 1947 and updated in 1994 as part of the WTO agreements.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_0ccc5c6f374007f420fde4','General Agreement on Trade in Services',ARRAY[]::text[],'The WTO treaty establishing rules and scheduled commitments for international trade in services across four modes of supply.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_a49a6e106ef80b95e41f90','General-purpose technology',ARRAY[]::text[],'A technology, such as electricity or computing, useful across many industries and capable of enabling further innovations.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_abe3d0980c66136c9ea526','Geographical indication',ARRAY[]::text[],'A sign identifying a product whose quality, reputation or other characteristic is linked to a particular geographic origin.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_a926afbac40426980bc28f','Global financial crisis',ARRAY[]::text[],'A major breakdown of international credit and banking markets; the 2007–09 episode spread from US housing finance to the global economy.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_94699122433b93ba90821d','Global systemically important bank',ARRAY[]::text[],'A bank designated as critical to global financial stability because of factors including size, interconnectedness and complexity.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_1823a8cf1ce0c687c5ddc5','Globalisation',ARRAY[]::text[],'Growing integration of economies through international trade, investment, finance, technology and cross-border movement of people.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_df8b576043ce0f13af0918','Goods-market equilibrium',ARRAY[]::text[],'An output level at which spending on domestically produced goods matches production in the model under consideration.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_82bce30eef877b893c981c','Government bond',ARRAY[]::text[],'A debt security issued by a public authority, with repayments governed by the bond''s terms and the issuer''s creditworthiness.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_a47dab027d7e8f637e5e9f','Government expenditure',ARRAY[]::text[],'Public-sector spending on goods, services, transfers and other uses, with its coverage depending on the fiscal statistic.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_e527007e69716eac3cc56b','Government failure',ARRAY[]::text[],'An outcome in which public intervention or political institutions produce avoidable inefficiency or fail to deliver intended benefits.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_111f5a87e8c2c7ca668688','Government revenue',ARRAY[]::text[],'Income received by government from taxes, social contributions, fees, investments and other sources.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_8501364836999c74b9d367','Gross capital formation',ARRAY[]::text[],'Total investment in fixed assets, changes in inventories and certain valuables, as defined in national accounts.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_83661bfe4356d283540c1b','Gross fixed capital formation',ARRAY[]::text[],'Acquisitions minus disposals of fixed assets used repeatedly in production, such as buildings, machinery and software.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_355e89015bc1f86655464f','Gross income',ARRAY[]::text[],'Income measured before specified deductions, such as personal taxes, with the precise meaning depending on the accounting context.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_70e44606664a7f9cf75d09','Gross value added',ARRAY[]::text[],'The value of output produced by a business, industry or sector minus the value of intermediate inputs consumed.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_5556c8219dc3075ea5e7f9','Harmonised Index of Consumer Prices',ARRAY[]::text[],'A standardised European measure of consumer price changes designed to make inflation rates comparable across countries.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_04aca45c752488c7703be7','Harmonized System',ARRAY[]::text[],'An international coding framework maintained by the World Customs Organization for classifying goods in customs and trade statistics.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_5019dbdb6977241c999f5c','High-quality liquid asset',ARRAY[]::text[],'An asset judged capable of being converted rapidly into cash in stressed markets, subject to regulatory eligibility criteria.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_dad4680b356a361c7ce27c','High-value payment system',ARRAY[]::text[],'A payment infrastructure designed to transfer large or time-critical sums between financial institutions securely.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_955205c69e106c9f9e7c87','Higher loss-absorbency requirement',ARRAY[]::text[],'Additional regulatory loss-absorbing resources required of certain systemically important financial institutions to reduce the consequences of failure.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_7f23cccea23863d755c7f6','House Price Index',ARRAY[]::text[],'A statistic tracking changes in residential property prices over time, usually using a specified sample or transaction data.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_9b92251fa9ed534606d438','Household debt-service burden',ARRAY[]::text[],'The share of a household''s income absorbed by contractual repayments on mortgages, personal loans and other debts.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_c1024ace8b09b9a47499e5','Household saving ratio',ARRAY[]::text[],'Household saving expressed as a share of the relevant disposable-income measure over a given period.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_b9986947b7f8f8306d4775','Human Development Index',ARRAY[]::text[],'A composite indicator combining health, education and income measures to compare broad human development across countries.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_6f27ed652bf06434bc1394','ILO unemployment measure',ARRAY[]::text[],'A survey-based unemployment definition covering people without work who are available for work and actively seeking employment, under specified criteria.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_03504ea18d3bcaf79eacb0','Implied price deflator',ARRAY[]::text[],'A price indicator calculated by dividing a current-price value by its corresponding inflation-adjusted volume measure.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_331ae74dea320f7e31ed04','Inactive working-age population',ARRAY[]::text[],'Working-age people neither in paid work nor actively seeking employment, including some students and unpaid carers.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_63bef8a6d61983992fb966','Inclusive trade union',ARRAY[]::text[],'A trade union that considers how its wage demands may affect employment across multiple firms or sectors.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_850fa11ccacbd5f11d03fb','Index number',ARRAY[]::text[],'A statistic showing how a variable has changed relative to a reference value, frequently set equal to 100 in a base period.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_2b0078f04033e17a66e2d2','Indifference curve',ARRAY[]::text[],'A curve showing combinations of goods that a consumer regards as giving the same level of satisfaction.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_2c27d53425e2594f7ce7c2','Indirect taxation',ARRAY[]::text[],'Taxes collected through the sale or use of goods and services, such as VAT and excise duties, rather than directly on income.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_b705dd5441f816376e8163','Individual savings account',ARRAY[]::text[],'A UK tax-advantaged account allowing eligible people to save or invest within annual subscription limits, subject to the rules of the chosen ISA type.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_a02613ef98e59bcbcf0770','Industrial Revolution',ARRAY[]::text[],'The transformation of production beginning in eighteenth-century Britain through mechanisation, factories and new sources of energy.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_733d905a221eb5954fbe61','Inequality aversion',ARRAY[]::text[],'A preference for avoiding unequal distributions of income, wealth or payoffs even when inequality might bring personal benefits.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_ddd2bb0720958a73efaf65','Infant industry',ARRAY[]::text[],'A young domestic industry that may initially have high costs while it develops experience, scale and productive capabilities.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_5f0d0914064d4f1f1c3ce0','Inflation-adjusted price',ARRAY[]::text[],'A monetary price expressed in the purchasing power of a common reference period, allowing comparisons across time.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_8a93a5dc6a9d17505be474','Initial margin',ARRAY[]::text[],'Collateral posted before or when entering certain financial contracts to cover potential future losses during close-out.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_d3440b69126d9c186fddc7','Innovation',ARRAY[]::text[],'The introduction or adoption of a new or improved product, process or organisational practice that creates economic value.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_fd5186c4528c860cfa4560','Insurance-linked security',ARRAY[]::text[],'A tradable financial instrument whose payments depend on insurance-related risks, such as natural disasters, transferring some risk to investors.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_a0983c6d715706b008fb4b','Intangible asset',ARRAY[]::text[],'A non-physical economic resource with value, such as software, intellectual property or a business''s acquired contractual rights.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_80ee07dcd8ec4a4aac7856','Interest coverage ratio',ARRAY[]::text[],'An indicator of a borrower''s capacity to pay financing costs, commonly calculated as earnings before interest and tax divided by interest expense.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_13c2f98c4b9b26e7bcad36','Interest rate risk in the banking book',ARRAY[]::text[],'Exposure of a bank''s economic value or earnings to changes in interest rates on non-trading assets and liabilities.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_d065c0ad4c57f5a3b98280','Intermediate consumption',ARRAY[]::text[],'Goods and services used up or transformed in the production process, excluding fixed assets and their depreciation.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_917470b1a5759452e31e90','Internal Capital Adequacy Assessment Process',ARRAY[]::text[],'A bank''s internal process for identifying material risks and assessing how much capital it needs beyond minimum requirements.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_9c49ce76327a19ffeccfda','Internal-ratings-based approach',ARRAY[]::text[],'A bank capital framework allowing approved institutions to use specified internal credit-risk estimates to determine parts of their regulatory capital requirements.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_576dd7895947fe526c386c','International Association of Insurance Supervisors',ARRAY[]::text[],'A global standard-setting organisation that develops guidance for insurance supervision and promotes cooperation between insurance regulators.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_49f5afb969cdd130e2ad56','International Financial Reporting Standards',ARRAY[]::text[],'Accounting standards designed to support consistent financial reporting across jurisdictions that require or permit their use.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_9409708c9d803a800a5714','International Monetary Fund',ARRAY[]::text[],'An international institution that supports monetary cooperation and financial stability, including through surveillance and lending.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_d53d0c175cc7028bf4dac4','International Organization of Securities Commissions',ARRAY[]::text[],'A global association of securities regulators that develops standards and encourages cooperation on financial-market oversight.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_21a128f049b78015a640d0','International Securities Identification Number',ARRAY[]::text[],'A standardised code uniquely identifying a specific issue of securities for trading and settlement purposes.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_5dab821e7ff76f97d1d253','Invention',ARRAY[]::text[],'The development of a new product, idea or method, whether or not it has yet been commercially adopted.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_7a1eabc3deb7fd02ceb1e1','Inventory',ARRAY[]::text[],'Goods, raw materials or work in progress held by a business for future use or sale.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_30c71593d061c2d41154ce','Isocost line',ARRAY[]::text[],'The different combinations of production inputs that a firm can purchase for a fixed total expenditure at given input prices.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_646503355f649d51cbd36f','Isoprofit curve',ARRAY[]::text[],'A set of price and quantity combinations that yield the same level of profit for a firm.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_490cbb9341f2aee58987d9','Labour Force Survey',ARRAY[]::text[],'A household survey used to estimate employment, unemployment, inactivity and other labour-market measures under standard statistical definitions.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_34542e5e2ea1b242bb06a4','Labour market matching',ARRAY[]::text[],'The process by which employers with vacancies and people seeking work find one another and form employment relationships.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_25537e66aebbc2ce5ad6ce','Least-developed country designation',ARRAY[]::text[],'A United Nations classification of countries facing severe structural barriers to development, used in trade-related special treatment.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_aac4d61cda7cd004501ee6','Leontief paradox',ARRAY[]::text[],'The historical finding that US exports appeared more labour-intensive than imports, challenging a simple factor-endowment prediction of trade.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_c91db3c2cfd86102dabcbe','Liability',ARRAY[]::text[],'An obligation to pay money or provide value to another party, recorded alongside assets in a balance sheet.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_ed9bf9dacfa947daad0a9b','Liability-driven investment',ARRAY[]::text[],'An investment approach focused on matching assets and their cash flows to expected liabilities, often used by pension funds.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_a7e0ff8f088a5e0654e7a8','Life-cycle assessment',ARRAY[]::text[],'A method for evaluating environmental impacts associated with a product or service from raw materials through production, use and disposal.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_a1e81de84699f67dc5aca1','Liquidity coverage ratio',ARRAY[]::text[],'A bank regulatory measure comparing high-quality liquid assets with projected net cash outflows over a 30-day stress scenario.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_458968e80a24092fbbbeb4','Lisbon Agreement on appellations',ARRAY[]::text[],'An international agreement providing a registration and protection system for specified appellations of origin.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_8d2e085c4238dccbc87fa4','Loan-to-income ratio',ARRAY[]::text[],'The size of a loan relative to a borrower''s annual income, commonly used as a mortgage affordability indicator.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_f05903fd0c88f454f7c4e6','Loan-to-value ratio',ARRAY[]::text[],'The size of a secured loan divided by the value of the underlying collateral, frequently used in mortgage risk assessment.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_4f585931111d936e5cf4c1','Local-content requirement',ARRAY[]::text[],'A rule requiring a business or investment project to use a minimum amount of locally produced goods, components or services.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_1581d4c70208a24830cf6c','Logarithmic scale',ARRAY[]::text[],'A scale on which equal distances represent equal ratios rather than equal absolute changes, often useful for comparing growth rates.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_56b44368d2c2177367d685','London Interbank Offered Rate',ARRAY[]::text[],'A former benchmark for interbank borrowing costs that was widely used in financial contracts before most settings were discontinued and replaced by alternative rates.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_42a7b5a12be3741b30762f','Long-run economic model',ARRAY[]::text[],'An economic model allowing adjustments such as entry, investment and changes in production capacity that cannot occur in the short run.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_e4a2ff6593a8431bd6f319','Long-run equilibrium',ARRAY[]::text[],'An equilibrium reached after variables fixed over shorter horizons, such as the number of firms, have had time to adjust.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_64990863f2cc4821436a22','Loss given default',ARRAY[]::text[],'The share or amount of a credit exposure expected to be lost if a borrower defaults after recoveries and relevant costs.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_7124967a51bd0615ddedd2','Madrid Agreement on marks',ARRAY[]::text[],'Part of the international treaty framework facilitating the registration and protection of trade marks across participating jurisdictions.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_f918c0b68ac8b335a331f5','Manufacturing sector',ARRAY[]::text[],'Industries that transform materials or components into new physical products using industrial processes.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_fa0335b96a7271b0d982d4','Marginal rate of substitution',ARRAY[]::text[],'The rate at which a consumer would exchange one good for another while remaining equally satisfied, represented by the slope of an indifference curve.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_f58a93b0523c92b41f1692','Marginal rate of transformation',ARRAY[]::text[],'The amount of one output that must be sacrificed to produce an additional unit of another, given available technology and resources.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_3c28127ab2ed03fbfa8a0f','Mark-to-market',ARRAY[]::text[],'Valuing an asset or liability using current market prices or the best available market-based estimates.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_ab5f1c74796a651ea662dc','Market bargaining process',ARRAY[]::text[],'Negotiation in which parties attempt to agree on prices or terms, with outcomes shaped by their alternative options and information.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_327f5cef3fe100e4d1a440','Market capitalisation rate',ARRAY[]::text[],'The return investors require to hold a company''s shares given their risk, influencing the present value of expected future payments.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_af578f5391905194d65539','Market-based finance',ARRAY[]::text[],'Financing provided through securities markets and non-bank intermediaries rather than traditional bank lending alone.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_69820a9ffa10a63983da03','Median voter',ARRAY[]::text[],'The voter positioned in the middle of an ordered distribution of preferences along one policy dimension, with equal numbers on either side.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_2da97b33f98f16483ba1e8','Medium-run economic model',ARRAY[]::text[],'A model horizon in which some quantities can adjust, such as employment and prices, while capital, technology or institutions remain fixed.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_e9072a9771f99f54414d94','Merchandise trade',ARRAY[]::text[],'International trade involving physical goods rather than cross-border services.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_00df82fc21990b18e43b7e','Minimum acceptable offer',ARRAY[]::text[],'The least favourable offer a participant would accept rather than refuse a deal, given their alternative options.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_90f8c65d3b476b81edde50','Minimum requirement for own funds and eligible liabilities',ARRAY[]::text[],'A UK bank resolution standard requiring sufficient capital and eligible debt to absorb losses and support recapitalisation.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_9db6dd7dcecef58d48bc29','Missing market',ARRAY[]::text[],'A situation in which potentially beneficial exchange does not occur because information, institutions or enforceable contracts are inadequate.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_1f6bfd9250e283325f4d19','Mixed income',ARRAY[]::text[],'The surplus generated by unincorporated household businesses that combines returns to owners'' labour and their capital.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_988733a6f40c97ba852d00','Modes of services supply',ARRAY[]::text[],'The four WTO categories of services trade: cross-border supply, consumption abroad, commercial presence and movement of natural persons.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_ccdce22e73618587fa7924','Monetary financial institution',ARRAY[]::text[],'A financial institution included in official monetary statistics because it accepts deposits or close substitutes and extends credit or invests in securities.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_a344f4a0ed7232c1a03f0c','Monetary Policy Committee',ARRAY[]::text[],'The Bank of England committee that decides the main UK monetary policy interest rate and other measures in pursuit of its inflation target.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_aa34740280e9a02d90eaf8','Monetary Policy Report',ARRAY[]::text[],'A Bank of England publication explaining the Monetary Policy Committee''s assessment of the economy, inflation outlook and monetary policy.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_0e65c32f771b590fcd5f17','Money market fund',ARRAY[]::text[],'An investment fund holding short-term, high-quality debt instruments and seeking to provide liquidity and relatively low volatility.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_b050c72cf827aef0593aa8','Monopoly rents',ARRAY[]::text[],'Extra earnings a seller can maintain because barriers or limited competition allow a price above a competitive benchmark.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_a2e99cb8c09f3c57e6afca','Montreal Protocol',ARRAY[]::text[],'A 1987 international agreement to phase out ozone-depleting substances, later expanded to control certain climate-warming chemicals.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_c6f67a87d4bc8458fea5be','Mortgage Credit Directive',ARRAY[]::text[],'European legislation establishing certain standards for residential mortgage lending, information and consumer protections.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_566c2719f63dcbb7dd7eb8','Mortgage loan',ARRAY[]::text[],'A loan secured by property, usually repaid with interest over an agreed term and enforceable against the collateral if payments fail.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_b56f4c6e06e1e850d168c0','Multifactor productivity',ARRAY[]::text[],'The portion of output growth not accounted for by measured growth in combined labour and capital inputs, often called total factor productivity.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_99ec01615c4c3a05b2f79a','Multilateral environmental agreement',ARRAY[]::text[],'A treaty involving multiple governments to address shared environmental problems such as hazardous waste, biodiversity or climate change.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_c07d2b9f28be47fe58b8cd','Multimodal transport',ARRAY[]::text[],'The movement of goods using more than one type of transport, such as combining shipping, rail and road in one journey.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_5985ba1a548ffcdc878817','Multiplier model',ARRAY[]::text[],'A macroeconomic framework showing how changes in autonomous spending lead to further rounds of changes in income and expenditure.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_f3d015b431df57f31225fd','National income',ARRAY[]::text[],'A measure of income earned by an economy''s residents from production and property, subject to the national-accounts definition used.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_4582a9370ee75262689e05','Natural person in services trade',ARRAY[]::text[],'An individual supplying services in another country, distinguished from a company or other legal entity under trade rules.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_029375c1cdbf64c21b42d2','Natural resource reserves',ARRAY[]::text[],'The quantity of a natural resource currently considered economically and technically extractable under specified conditions.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_4a5cc1bce1f30af60d6b54','Negative feedback mechanism',ARRAY[]::text[],'A process in which an initial change triggers forces that counteract it and push the system towards stability.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_e0d76691fe7b0a2ce52d95','Net asset value',ARRAY[]::text[],'The total value of an investment fund''s assets minus liabilities, often divided by outstanding units to calculate value per share.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_af71a55509dad56b34ccd4','Net capital flows',ARRAY[]::text[],'The net amount of financing moving into or out of an economy through cross-border transactions in financial assets and liabilities.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_423317db20ab738d25d5e2','Net income after depreciation',ARRAY[]::text[],'An accounting measure of income after deducting the cost of wear and obsolescence of productive capital from a gross amount.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_7f67aa38e7fc30800d99ad','Net interest income',ARRAY[]::text[],'The interest a financial institution earns on assets minus the interest it pays on liabilities over a period.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_5755cfdb2fa3d10659ef46','Net interest margin',ARRAY[]::text[],'A bank''s net interest income divided by a relevant measure of interest-earning assets, indicating profitability from intermediation.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_3b27fe9971c2ce40d1a081','Net international investment position',ARRAY[]::text[],'The value of a country''s external financial assets minus its external financial liabilities at a particular date.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_82eecf51dc2d054bbe620c','Net stable funding ratio',ARRAY[]::text[],'A regulatory measure assessing whether a bank has sufficiently stable funding for its assets and activities over a one-year horizon.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_9ccb943e0790b75d2400f2','Net worth',ARRAY[]::text[],'The value of assets owned by a person or organisation minus the value of its liabilities.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_cb4c440562a3d752317acb','Network external effect',ARRAY[]::text[],'An impact on other people''s welfare arising because users or activities are connected through a network.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_b1eb74351622839d0ba1ab','New Deal',ARRAY[]::text[],'The programme of US economic reforms and public works introduced under President Franklin D. Roosevelt from 1933 in response to the Great Depression.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_30d22d278f77992db76900','Non-bank financial institution',ARRAY[]::text[],'A business providing financial intermediation or services outside traditional deposit-taking banking, such as an insurer, investment fund or finance company.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_d993d7f99b75a37bf5980f','Non-performing loan',ARRAY[]::text[],'A loan whose repayments are materially overdue or unlikely to be paid in full, under the applicable supervisory definition.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_0cb14bca05a10291ae65ec','Non-profit institutions serving households',ARRAY[]::text[],'Private non-profit organisations such as charities and associations that provide goods or services to households without aiming to distribute profits.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_fe962056660b90136b35ad','Non-seasonally adjusted data',ARRAY[]::text[],'A time series that retains variations caused by the calendar and recurring seasons, rather than removing them statistically.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_99b751246bf2170f852561','Normal profit',ARRAY[]::text[],'A return just sufficient to cover all costs including the opportunity cost of capital, corresponding to zero economic profit.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_101f26a9d15193038d7779','Nullification or impairment',ARRAY[]::text[],'The reduction of an expected benefit under a WTO agreement as a result of another member''s measure, assessed under trade dispute rules.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_426faf39169b33b1578fb0','Office for Budget Responsibility',ARRAY[]::text[],'The UK''s independent public body producing economic and fiscal forecasts and assessing sustainability of the public finances.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_7c719d4ce1acc370aded2f','Official standing facilities',ARRAY[]::text[],'Central-bank arrangements allowing eligible institutions to deposit or borrow overnight funds against the relevant terms and collateral.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_cb8394316f4e720bfc6737','Offshoring',ARRAY[]::text[],'Moving a business activity to another country, whether within the same company or through an outside supplier.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_d519d5d404614a779511f0','Okun''s coefficient',ARRAY[]::text[],'An empirical estimate of how much unemployment tends to change in response to changes in economic growth or the output gap.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_cbcc8cbdc749f2344fdf8e','Okun''s law',ARRAY[]::text[],'An observed inverse association between economic growth and changes in unemployment, with the estimated strength varying across economies.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_43fcdbb2ca4c05164df07b','Open-ended investment fund',ARRAY[]::text[],'A collective investment fund that normally issues or redeems units in response to investor subscriptions or withdrawals, creating possible liquidity-management demands.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_af660a1b98514474702796','Operational resilience',ARRAY[]::text[],'The ability of financial firms and market systems to prevent, withstand and recover from disruptions while continuing critical services.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_1149483b0b5d400f405a97','Opportunity set',ARRAY[]::text[],'The choices available to a decision-maker given their resources, constraints and the prevailing environment.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_ba9849f8df8f59c27ca2e5','Output per worker',ARRAY[]::text[],'Labour productivity calculated as total output divided by the number of workers employed, rather than total hours worked.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_2d551811cc5d5c186aceca','Over-the-counter trading',ARRAY[]::text[],'Buying and selling financial contracts directly or through dealers rather than on a central organised exchange.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_efdd1961bf029e39019eac','Overnight index swap',ARRAY[]::text[],'A derivative exchanging a fixed interest rate for a floating payment linked to a compounded overnight reference rate.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_8073995ed2f7ea9f37301f','Pareto efficiency frontier',ARRAY[]::text[],'The set of feasible allocations where improving one person''s welfare would require making someone else worse off.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_bc2ec668368c1c0e9ca859','Paris Convention for industrial property',ARRAY[]::text[],'A treaty setting international principles for protecting patents, trade marks and other forms of industrial property.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_109a27f8facbd4ebb1a882','Payment service provider',ARRAY[]::text[],'An organisation providing services that allow customers to make or receive payments, including banks and regulated non-bank firms.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_da437f604a7f8265a5df07','Payment Systems Regulator',ARRAY[]::text[],'The UK authority overseeing designated payment systems, with objectives including competition, innovation and the interests of payment-service users.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_947900269e3bcf6b026c4c','Pension Protection Fund',ARRAY[]::text[],'A UK statutory fund providing specified compensation to members of eligible defined-benefit pension schemes whose sponsoring employer becomes insolvent.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_1b8dce14f1eac39d0a26db','Piece-rate pay',ARRAY[]::text[],'A wage arrangement where workers receive a payment for each unit of output completed rather than solely for time worked.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_494de4290cdffc8915a73f','Pigouvian subsidy',ARRAY[]::text[],'Public financial support intended to encourage activities that create positive benefits for others, such as some research or vaccinations.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_9bad85ae2e4af532046e26','Political trilemma of the world economy',ARRAY[]::text[],'The argument that deep economic integration, national sovereignty and full democratic political choice cannot all be maximised simultaneously.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_2995bc363b43853c652d5a','Positive feedback mechanism',ARRAY[]::text[],'A process in which an initial change triggers forces that amplify the original movement rather than dampening it.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_5265f9c33f4390f60c8c4c','Potential future exposure',ARRAY[]::text[],'An estimate of how large a derivative exposure could become because of future market movements before a contract expires.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_8952c1b415ca387c84edf6','Preshipment inspection',ARRAY[]::text[],'Independent verification of shipment characteristics such as quantity, quality and price before goods leave the exporting country.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_76aeb282ef995d2937eafd','Price gap in trade',ARRAY[]::text[],'The difference in the price of a product between markets, which may reflect tariffs, transport costs or other trade frictions.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_df0444a5a082ad28f1728b','Price undertaking in trade',ARRAY[]::text[],'An exporter''s commitment to revise its pricing, accepted under specified conditions, as an alternative to an anti-dumping measure.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_37c09b37a2c6a5347dbfdf','Price-based environmental policy',ARRAY[]::text[],'An approach using taxes, fees or subsidies to change the incentives attached to environmentally harmful or beneficial activities.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_4f9554265a6e0501a4d0dd','Price-setting power',ARRAY[]::text[],'The ability of a firm to set prices above marginal cost without losing all customers, owing to differentiation or restricted competition.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_028ce74229468ff4fa823f','Primary labour market',ARRAY[]::text[],'The part of the workforce characterised by relatively stable jobs, career progression and stronger employment protections.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_9b68be78273f6e5e33a2be','Principles for Financial Market Infrastructures',ARRAY[]::text[],'International standards for payment, clearing, settlement and related systems intended to reduce operational and financial risks.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_8ecba38e5918dc022ee303','Probability of default',ARRAY[]::text[],'An estimate of the likelihood that a borrower fails to meet contractual obligations over a specified period.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_97a58192b712528d6d290d','Procedural fairness',ARRAY[]::text[],'An assessment of whether a decision was reached through a fair process, regardless of how equal or unequal its outcome appears.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_c59f76cbb46c0f1b27ba05','Process and production method',ARRAY[]::text[],'The manner in which a good is manufactured or produced, which can be relevant to technical standards and environmental trade measures.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_1dc3b7a7814caa21d72c2c','Producer input prices',ARRAY[]::text[],'Prices manufacturers or other producers pay for materials, fuel and other goods used in production.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_5771e51862ad35ffe2b2a6','Producer output prices',ARRAY[]::text[],'Prices received by producers for goods they sell, before downstream wholesale or retail margins.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_b225547f963265aec5585d','Prudential regulation',ARRAY[]::text[],'Rules and supervision intended to keep financial institutions adequately capitalised, liquid and well managed so they can withstand losses.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_e3132a8eb760796a9427a5','Prudential Regulation Authority',ARRAY[]::text[],'The UK authority that supervises the safety and soundness of banks, insurers and certain major investment firms.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_cdbc8342d84a3a0ce98ee8','Purchasing Managers'' Index',ARRAY[]::text[],'A survey-based indicator summarising changes in business activity, such as orders, production and employment, relative to the previous month.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_1755135303e586abb753a4','Pure time preference',ARRAY[]::text[],'A tendency to value otherwise identical consumption more highly now than later simply because it occurs earlier.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_77bc98cfdfdd8f3f3f341e','Quantitative import restriction',ARRAY[]::text[],'A government rule that limits the amount or value of certain products permitted to enter a country over a specified period.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_38515ab9deb883012f48ab','Quantity-based environmental policy',ARRAY[]::text[],'A policy using direct limits on emissions or activities, such as caps and regulations, instead of relying solely on price incentives.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_316b2f099bfc8ef1c6d775','Quarterly national accounts',ARRAY[]::text[],'A set of economic accounts compiled every three months to measure output, expenditure, income and related aggregates.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_1f3467780f8ff9024f2741','Race to the bottom',ARRAY[]::text[],'Competition among jurisdictions to attract businesses by weakening standards or cutting taxes in ways that may harm collective welfare.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_283f287b2c401488a9759f','Radical innovation',ARRAY[]::text[],'A major new product or production method that combines knowledge in substantially different ways and can reshape existing industries.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_edc0fdf2d237b6439f6628','Rationed good',ARRAY[]::text[],'A product allocated by a rule other than willingness to pay, such as queues, eligibility criteria or lotteries when demand exceeds supply.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_0e56fef08b831496451b69','Real exchange rate',ARRAY[]::text[],'A measure of the relative price of goods and services between economies after accounting for the nominal exchange rate.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_726250f60205e1fd5d5684','Real household disposable income',ARRAY[]::text[],'Household income available after taxes and transfers, adjusted for changes in the price level.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_8e2eb15c361cf53b74b1a9','Real-time gross settlement',ARRAY[]::text[],'A payment system in which transfers are settled individually and finally in central-bank money as they are processed.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_08a1315a5d69c4aa9b801c','Reciprocity in economic behaviour',ARRAY[]::text[],'The tendency to reward helpful or cooperative behaviour and respond negatively to perceived unfairness or exploitation.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_1db74bf11d276bfb17cb73','Regulatory technology',ARRAY[]::text[],'Software and data tools used to help financial firms meet regulatory obligations or help supervisors monitor compliance.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_d3cab1b855c7153f31c76f','Relative price',ARRAY[]::text[],'The price of one good compared with another, indicating the trade-off facing buyers and producers.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_1fe103ae250a4b47c91d24','Remittances',ARRAY[]::text[],'Money transferred by migrants to relatives or other recipients in their country of origin, often supporting household income and foreign exchange receipts.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_c1bf94a952d7ce7d88b771','Rent ceiling',ARRAY[]::text[],'A legally imposed maximum rent that can be charged for specified properties, potentially creating shortages when set below market-clearing levels.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_88f91dd22016e6daaa1a45','Research and development',ARRAY[]::text[],'Spending on systematic work to discover new knowledge, improve technologies or develop products and processes.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_77a01094f822e7b9127a99','Reservation indifference curve',ARRAY[]::text[],'A curve describing allocations that leave a participant as well off as the option they would choose if negotiations failed.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_08e4f1b1be2682f72faf80','Retail Prices Index',ARRAY[]::text[],'A longstanding UK measure of consumer price change that differs from CPI in its basket and calculation methods and is no longer a National Statistic.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_ca0fb8c5154da444433fe1','Return on assets',ARRAY[]::text[],'Net income divided by average total assets, used to assess how efficiently a firm generates profit from its asset base.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_7287c3ba2e95436295194c','Return on equity',ARRAY[]::text[],'Net income attributable to shareholders divided by average equity, measuring profit relative to owners'' invested capital.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_d144f14345be55b416491b','Return on tangible equity',ARRAY[]::text[],'Profit attributable to common shareholders compared with tangible common equity, excluding certain intangible assets from the denominator.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_c95342eaf0bd48aca8b0e8','Reverse causality',ARRAY[]::text[],'A challenge in causal analysis in which the supposed outcome may itself influence the suspected cause, potentially reversing the direction of explanation.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_e2dc82c9b5b76d2d9e7fe7','Revolving credit facility',ARRAY[]::text[],'A lending arrangement permitting a borrower to draw, repay and redraw funds within an agreed limit and term.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_fa6c473858e2ed4a64de8d','Risk-free reference rate',ARRAY[]::text[],'An interest-rate benchmark based on transactions designed to have minimal bank-credit risk, used in loans and derivatives.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_5efe1e64114b837c8b65c1','Safeguard measure',ARRAY[]::text[],'A temporary trade restriction allowed under specific rules when a sudden rise in imports causes or threatens serious injury to a domestic industry.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_33a7d0afc23b7ed7354618','Sanitary and phytosanitary measure',ARRAY[]::text[],'A trade-related rule intended to protect human, animal or plant health from specified risks, such as unsafe food or pests.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_4d78a885ffb46b1a46e6ee','Scarcity',ARRAY[]::text[],'The fact that available resources cannot satisfy every possible use, making choices and opportunity costs unavoidable.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_97ed717a9dc14093a4d626','Seasonal adjustment',ARRAY[]::text[],'A statistical procedure to remove regular seasonal and calendar patterns from data so underlying changes are easier to compare.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_bac9927fcb6a455e5e80ff','Secondary labour market',ARRAY[]::text[],'The part of the workforce characterised by relatively insecure jobs, weaker protections and limited progression.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_8ae33d813c1ad8563ff4a2','Section 166 skilled person review',ARRAY[]::text[],'An independent examination commissioned under UK financial-services law to investigate specified aspects of a regulated firm''s activities or controls.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_15bca89d58c8ee6323c671','Secured Overnight Financing Rate',ARRAY[]::text[],'A US dollar reference interest rate based on overnight transactions secured by US Treasury securities, widely used as an alternative to US dollar LIBOR.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_4f262ed32cde994cee9c4f','Securities financing transaction',ARRAY[]::text[],'A transaction involving lending or borrowing securities or cash against securities, including repurchase agreements.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_4fe5bed7c1f657f5963392','Segmented labour market',ARRAY[]::text[],'A labour market divided into groups with distinct wages or conditions and barriers preventing workers from moving easily between them.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_6dfa45c43110f1a83461ce','Self-insurance',ARRAY[]::text[],'Using personal savings or other resources to absorb losses instead of transferring risk to an insurer.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_bb1f583452a7fbea024bdc','Senior Managers and Certification Regime',ARRAY[]::text[],'The UK framework allocating accountability to senior financial-services managers and assessing fitness for specified staff roles.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_474085186db18f1215e08a','Service-sector schedule of commitments',ARRAY[]::text[],'A WTO member''s list of binding undertakings and limitations on access to its services markets under the GATS framework.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_6b769585c35ad3a3650e5f','Services Producer Prices Index',ARRAY[]::text[],'An index measuring changes in prices charged by providers in selected service industries.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_b07a4abe2fb9a67ef83d3e','Short-run economic model',ARRAY[]::text[],'An economic model examining decisions while certain factors, such as capacity, prices or contractual wages, remain fixed.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_03418c0e4473c89594147b','Short-run equilibrium',ARRAY[]::text[],'An equilibrium that holds while some variables are fixed but may change once firms and households have time to adjust.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_90466ba2b42c1213b9de4d','Short-termism',ARRAY[]::text[],'Placing excessive importance on immediate gains or costs at the expense of longer-term consequences.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_6762685ed1b252b547eb4d','Small and medium-sized enterprise',ARRAY[]::text[],'A business classified as small or medium using criteria such as staff numbers, turnover and balance-sheet size.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_6a7bf6f322b3e135c8662a','Social discounting',ARRAY[]::text[],'The practice of assigning present values to costs and benefits that occur in future periods when evaluating collective policy choices.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_de9eedb962fd2d700fd657','Social insurance',ARRAY[]::text[],'Collectively financed protection against risks such as unemployment, illness or disability, often provided through government programmes.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_947d30f5aeee91d0b2ad81','Social interaction',ARRAY[]::text[],'A situation where one person''s decisions affect other people''s outcomes as well as their own.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_f03d5a9f528b843eabe1a1','Solvency capital requirement',ARRAY[]::text[],'The amount of eligible capital an insurer must hold under the applicable solvency regime to withstand specified risks over a defined horizon.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_8cd1459c639b5df6ae69ea','Special and differential treatment',ARRAY[]::text[],'Trade-agreement provisions giving developing and least-developed WTO members specified flexibilities or assistance.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_231b36d426854759dbb330','Special purpose vehicle',ARRAY[]::text[],'A legally separate entity created for a defined financing or business purpose, often used to hold assets or issue securities.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_612ee96aeb64672517fb2a','Specific commitment in services trade',ARRAY[]::text[],'A market-access or national-treatment undertaking listed by a WTO member for particular service sectors under GATS.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_2304079b8c8fc83a05d301','Specific tariff',ARRAY[]::text[],'A customs duty charged as a fixed amount per physical unit of imports, such as a sum per kilogram or item.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_5b9d04a4159606ff53f560','Speculation',ARRAY[]::text[],'Taking a financial position in anticipation of future price changes rather than primarily to use the underlying asset.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_fc2c8332cbc5e890b73a74','Standard Industrial Classification',ARRAY[]::text[],'A standard system of codes grouping businesses or activities by the type of industry in which they operate.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_b3b951c0c161b1824b2c1b','Stationary state in growth theory',ARRAY[]::text[],'A long-run condition in a model where major per-person economic variables cease to grow because offsetting forces balance without technological progress.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_b5b9e53bafb85eba3c0049','Sterling Monetary Framework',ARRAY[]::text[],'The Bank of England''s framework of operations and facilities for providing sterling liquidity, implementing monetary policy and supporting market functioning.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_a8c77a5006f291d5b1fe00','Sterling Overnight Index Average',ARRAY[]::text[],'A reference interest rate based on eligible overnight unsecured sterling transactions, administered by the Bank of England and used across sterling financial contracts.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_00de7c5f8ff2c84b2168ab','Stock exchange',ARRAY[]::text[],'An organised marketplace for trading listed shares and other eligible financial instruments.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_c70410051002c4bb11f23c','Stress testing exploratory scenario',ARRAY[]::text[],'A financial-system exercise evaluating how institutions could respond to a severe but plausible scenario, often used to identify vulnerabilities rather than set immediate capital requirements.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_bf6e8b3ea6e5c648ee7b79','Stress testing of banks',ARRAY[]::text[],'Using severe but plausible economic or market scenarios to assess a bank''s ability to withstand losses and funding pressures.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_e7200936b66ef558e67168','Stressed value at risk',ARRAY[]::text[],'A value-at-risk measure calculated using market conditions from a severe historical stress period to better capture risks beyond normal conditions.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_8b233cc3124bf36d4b1953','Structured investment vehicle',ARRAY[]::text[],'A financial entity that historically financed portfolios of longer-term securities using shorter-term borrowing, creating refinancing and liquidity vulnerabilities.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_e88cbcf62406f18dc07cdf','Subsistence level',ARRAY[]::text[],'A minimum standard of consumption sufficient to maintain basic survival, used in some historical and development-economic models.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_6aca7c4abd442c86cefc41','Substantive fairness',ARRAY[]::text[],'An assessment of the fairness of an outcome itself, such as its distribution of income or rights, rather than the decision-making procedure.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_aee7eb1a9ad17f52d306f8','Supply side of a market',ARRAY[]::text[],'The producers or sellers willing and able to offer goods or services at different prices.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_33eef784d1f5947944ee6e','Supply-side economic policy',ARRAY[]::text[],'Measures intended to increase an economy''s capacity to produce, such as improving education, infrastructure, incentives or competition.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_a0e2d6609b4e3aa5d864e3','Supply-side macroeconomic model',ARRAY[]::text[],'An approach analysing how labour, capital, institutions and technology determine the economy''s productive potential.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_5c6690253e3ac505d12067','Systemic risk buffer',ARRAY[]::text[],'A regulatory capital buffer that can be applied to banks to address structural systemic risks to financial stability.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_11b6f4eed71c5d58d5205c','Systemically important financial institution',ARRAY[]::text[],'A financial firm whose failure could cause major disruption because of its scale, connections or role in key markets.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_d2bf02c759e958925c93bd','Tangency condition',ARRAY[]::text[],'A point at which two curves touch with a common slope, often marking an optimum where a consumer''s trade-offs match market trade-offs.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_62e4ebeefdf0c1f324a768','Target wealth',ARRAY[]::text[],'A level of accumulated assets that a household aims to maintain in light of its expected needs, income and risks.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_898ae9b56ee4b91fb9945b','Tariff binding',ARRAY[]::text[],'A commitment under trade rules not to raise an applied customs duty above an agreed maximum rate without following the relevant procedures.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_ea7a665872877bfde989e6','Tariff concession',ARRAY[]::text[],'A negotiated commitment to reduce or limit an import tariff, commonly recorded in a country''s trade schedule.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_9cf30dca9558e13128fa54','Tariff escalation',ARRAY[]::text[],'A pattern in which tariff rates rise as imported goods undergo further processing, often protecting domestic manufacturing activities.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_8a3a8238abd7306cc71fcb','Tariff peak',ARRAY[]::text[],'A relatively high duty applied to a particular product or sector despite generally lower tariff rates across the rest of an economy.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_237c75fd85042d97fd2c2c','Tariff schedule',ARRAY[]::text[],'A formal list setting out a country''s tariff commitments for different products, including bound rates and applicable conditions.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_08c6a7bee54dbf470226f8','Taylorism',ARRAY[]::text[],'An approach to industrial management associated with Frederick Taylor, emphasising detailed task measurement, standardisation and control of labour.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_18c99090951f0027a4e2c2','Technically feasible allocation',ARRAY[]::text[],'A distribution or production plan achievable using existing technology and resources, regardless of whether participants prefer it.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_07deaee435990908b5105c','Technological progress',ARRAY[]::text[],'Changes in methods or knowledge that allow more output to be produced from given resources or comparable output with fewer inputs.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_152090bb722326e2dc6404','Tier 2 bank capital',ARRAY[]::text[],'A lower-ranking category of regulatory bank capital composed of eligible instruments that absorb losses mainly when the bank becomes non-viable or is resolved.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_38979dc3ba21aaeaf8c7bf','Total loss-absorbing capacity',ARRAY[]::text[],'A standard requiring large systemic banks to maintain sufficient eligible equity and debt to absorb losses and support orderly resolution.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_5c1b773b9af114aa0be549','Trade policy transparency',ARRAY[]::text[],'The openness and predictability of governments'' trade rules, policy decisions and administrative practices.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_c091644ceed5300b915a2e','Trade-balancing requirement',ARRAY[]::text[],'An investment-related condition tying the right to import inputs or goods to the value of the firm''s exports.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_c484c42f6c4003fea23a55','Trade-related investment measure',ARRAY[]::text[],'A policy affecting foreign investment that also alters trade in goods, including some local-content or trade-balancing requirements.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_680f92223f2e85ebd9178e','Trade-remedy circumvention',ARRAY[]::text[],'Steps taken to avoid an anti-dumping, countervailing or other trade restriction by altering routes or arrangements without changing the underlying economic activity.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_32b1a860134701928bcfbf','Transaction costs',ARRAY[]::text[],'Costs of making an exchange or agreement, including searching for partners, negotiating terms, verifying information and enforcement.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_dc5d2b730dc406c028aaf4','TRIPS Agreement',ARRAY[]::text[],'The WTO Agreement on Trade-Related Aspects of Intellectual Property Rights, setting minimum standards for protecting and enforcing specified rights.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_203bc437501d9c1eaec836','UK Blue Book',ARRAY[]::text[],'The annual UK National Accounts publication setting out detailed estimates of national output, income and expenditure.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_e184ec87a397b8e461c056','UK Debt Management Office',ARRAY[]::text[],'The UK government agency responsible for central-government debt issuance and cash management on behalf of HM Treasury.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_efcde80018d4ba4d02412b','Unemployment benefit',ARRAY[]::text[],'A public payment supporting eligible people who are out of paid work, subject to the conditions of the relevant social-protection system.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_2a78cbdaaeea6f6ec38df1','Unemployment insurance replacement rate',ARRAY[]::text[],'The share of a worker''s former earnings provided by unemployment-related benefits, commonly measured before or after tax.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_e54aaade003fb65650b9e8','Unit labour costs',ARRAY[]::text[],'Labour compensation per unit of output, used to assess the relationship between employee costs and productivity.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_2e95b8c22fd60feac23ab7','United Nations Conference on Trade and Development',ARRAY[]::text[],'A United Nations body working on trade, investment, finance and development, particularly challenges affecting developing economies.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_6cd435014b615826c49bef','Uruguay Round',ARRAY[]::text[],'The multilateral trade negotiations held from 1986 to 1994 that created the World Trade Organization and broadened international trade rules.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_5dfa276ae58a03e65d37b7','Utility in economics',ARRAY[]::text[],'A representation of how strongly someone prefers different outcomes, used to analyse choice rather than directly measure happiness.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_c3af5983ed4f7a8b8fdc97','Value added tax',ARRAY[]::text[],'A consumption tax collected at successive stages of production and distribution, with registered businesses normally reclaiming tax on eligible inputs.','https://www.ons.gov.uk/economy/nationalaccounts/uksectoraccounts/methodologies/glossaryofeconomicterms',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_c4263984ca2d348bafd050','Value at risk',ARRAY[]::text[],'A statistical estimate of the potential loss on a portfolio over a specified period at a chosen confidence level under a model''s assumptions.','https://www.bankofengland.co.uk/glossary',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_c12e850f916f347f04bf33','Variable import levy',ARRAY[]::text[],'A customs charge whose rate moves with market or administered prices, often to stabilise domestic agricultural prices.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_dd040ec1de793ee4949fd1','Verifiable information',ARRAY[]::text[],'Information that can be checked by a third party such as a court, enabling it to be used to enforce a contract.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_c500d208bf59192b1aa80a','Voluntary export restraint',ARRAY[]::text[],'An arrangement under which an exporting country or industry agrees to limit shipments to an importing market rather than face restrictions imposed there.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_a5473df5de9df942f788fc','Wage labour',ARRAY[]::text[],'Employment in which workers provide labour under an employer''s direction in return for agreed payment.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_1b00f71a5d274fe3780eb3','Weakness of will',ARRAY[]::text[],'Failing to follow a previously chosen plan because short-term temptations override longer-term goals, potentially causing subsequent regret.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_dfbd8f6399ab3b70522e56','Welfare state',ARRAY[]::text[],'The institutions and public programmes that protect citizens against economic risks and provide support such as pensions, healthcare and unemployment benefits.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_cf83bd8a844f1e60614c13','Worker''s best-response function',ARRAY[]::text[],'A model relating the effort workers optimally choose to the wage and other incentives offered by an employer.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_16f60d2ccf63b08c09bac7','World Customs Organization',ARRAY[]::text[],'An intergovernmental organisation that develops customs standards, including the international Harmonized System of product classification.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_3122619dd3e6c5524a4bd4','World Intellectual Property Organization',ARRAY[]::text[],'A United Nations agency administering international intellectual-property treaties and supporting cooperation on protection of inventions and creative works.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_282d57fcef8703d22c7b12','World Trade Organization',ARRAY[]::text[],'The international institution, established in 1995, that administers trade agreements, hosts negotiations and provides dispute settlement procedures.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_bb82818d6127f026a3886d','WTO Dispute Settlement Body',ARRAY[]::text[],'The WTO body composed of member governments that administers the formal process for resolving disputes about trade agreements.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_3aa201b581d261f8781e9f','WTO dispute-settlement panel',ARRAY[]::text[],'A group of independent experts appointed to examine a trade complaint and issue findings under the WTO''s dispute-settlement procedures.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_d5686bdb09ccfac4e274d5','WTO market-access commitment',ARRAY[]::text[],'A binding promise limiting certain barriers to foreign goods or services under a member''s international trade obligations.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_0e871eb3d5db62029cdf2b','WTO Trade Policy Review Mechanism',ARRAY[]::text[],'A process through which WTO members periodically examine each other''s trade policies to improve transparency and understanding.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_71953d4f400e9f2f3e2abb','WTO waiver',ARRAY[]::text[],'Formal permission under WTO rules for a member to depart temporarily from a particular obligation under specified conditions.','https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc')),
  ('cg2611_d94005c4455a22d76e4bb6','Zero lower bound on interest rates',ARRAY[]::text[],'A traditional theoretical limit near zero on nominal rates imposed by the option of holding cash, although some central-bank rates have been negative.','https://www.core-econ.org/glossary/',true,(now() AT TIME ZONE 'utc'),(now() AT TIME ZONE 'utc'))
